/* Generated by `helix family machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type IndicatorContext, type IndicatorInput, arrive, arrived, ask, blank, depart, fresh, gone, moves, neverPlaced, skip, take, traveling, withdraw } from './machine.js'

export type { IndicatorContext, IndicatorInput } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'indicator'

/** The state `moving`. */
export const STATE_MOVING = 0
/** The state `placed`. */
export const STATE_PLACED = 1
/** The state `unplaced`. */
export const STATE_UNPLACED = 2
/** Each state's name, by its number. */
export const STATES = ['moving', 'placed', 'unplaced'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['moving', 'placed', 'unplaced'] as const

/** The event `CHANGE`. */
export const EVENT_CHANGE = 0
/** The event `MEASURED`. */
export const EVENT_MEASURED = 1
/** The event `LANDED`. */
export const EVENT_LANDED = 2
/** Each event's name, by its number. */
export const EVENTS = ['CHANGE', 'MEASURED', 'LANDED'] as const

/** The effect `measure`. */
export const EFFECT_MEASURE = 0
/** The effect `put`. */
export const EFFECT_PUT = 1
/** The effect `glide`. */
export const EFFECT_GLIDE = 2
/** The effect `land`. */
export const EFFECT_LAND = 3
/** The effect `hide`. */
export const EFFECT_HIDE = 4
/** The effect `deadline`. */
export const EFFECT_DEADLINE = 5
/** The effect `deadline-end`. */
export const EFFECT_DEADLINE_END = 6
/** Each effect's name, by its number. */
export const EFFECTS = ['measure', 'put', 'glide', 'land', 'hide', 'deadline', 'deadline-end'] as const

/** Each request event's name, by its number. */
export const ASKS = [] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: IndicatorContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (context: IndicatorContext): number =>
  neverPlaced(context) ? STATE_UNPLACED : traveling(context) ? STATE_MOVING : STATE_PLACED

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (state: number): readonly Effect[] => {
  switch (state) {
    case STATE_MOVING:
      return [[EFFECT_DEADLINE, { ms: 1000, owner: 0 }]]
  }
  return []
}

/** What `moving` does with each event. */
const inMoving = (context: IndicatorContext, event: number, input: IndicatorInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_CHANGE:
      return { context: ask(context), effects: [[EFFECT_MEASURE]], state: STATE_MOVING }
    case EVENT_MEASURED:
      return blank(context, input) ? { context: skip(context), effects: [], state: STATE_MOVING } : gone(context, input) ? { context: withdraw(context), effects: [[EFFECT_HIDE]], state: STATE_MOVING } : moves(context, input) ? { context: depart(context, input), effects: [[EFFECT_DEADLINE_END, { owner: 0 }], [EFFECT_GLIDE], [EFFECT_DEADLINE, { ms: 1000, owner: 0 }]], state: STATE_MOVING } : fresh(context, input) ? { context: take(context, input), effects: [[EFFECT_PUT]], state: STATE_MOVING } : undefined
    case EVENT_LANDED:
      return arrived(context, input) ? { context: arrive(context), effects: [[EFFECT_DEADLINE_END, { owner: 0 }], [EFFECT_LAND]], state: STATE_PLACED } : undefined
  }
  return undefined
}

/** What `placed` does with each event. */
const inPlaced = (context: IndicatorContext, event: number, input: IndicatorInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_CHANGE:
      return { context: ask(context), effects: [[EFFECT_MEASURE]], state: STATE_PLACED }
    case EVENT_MEASURED:
      return blank(context, input) ? { context: skip(context), effects: [], state: STATE_PLACED } : gone(context, input) ? { context: withdraw(context), effects: [[EFFECT_HIDE]], state: STATE_PLACED } : moves(context, input) ? { context: depart(context, input), effects: [[EFFECT_GLIDE], [EFFECT_DEADLINE, { ms: 1000, owner: 0 }]], state: STATE_MOVING } : fresh(context, input) ? { context: take(context, input), effects: [[EFFECT_PUT]], state: STATE_PLACED } : undefined
  }
  return undefined
}

/** What `unplaced` does with each event. */
const inUnplaced = (context: IndicatorContext, event: number, input: IndicatorInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_CHANGE:
      return { context: ask(context), effects: [[EFFECT_MEASURE]], state: STATE_UNPLACED }
    case EVENT_MEASURED:
      return blank(context, input) ? { context: skip(context), effects: [], state: STATE_UNPLACED } : gone(context, input) ? { context: skip(context), effects: [], state: STATE_UNPLACED } : fresh(context, input) ? { context: take(context, input), effects: [[EFFECT_PUT]], state: STATE_PLACED } : undefined
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: IndicatorContext, event: number, input: IndicatorInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_MOVING:
      return inMoving(context, event, input)
    case STATE_PLACED:
      return inPlaced(context, event, input)
    case STATE_UNPLACED:
      return inUnplaced(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (state: number, context: IndicatorContext, owner: number): Move | undefined => {
  switch (state) {
    case STATE_MOVING:
      return owner === 0 ? { context: arrive(context), effects: [[EFFECT_DEADLINE_END, { owner: 0 }], [EFFECT_LAND]], state: STATE_PLACED } : undefined
  }
  return undefined
}

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: IndicatorContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
